func longestSubarrayDivByK(nums []int, k int) (res int) {
	firstPos := make([]int, k)
	for i := range firstPos {
		firstPos[i] = -2
	}

	firstPos[0] = -1
	s := 0
	for i, x := range nums {
		s = (s + x%k + k) % k // 保证 s 非负
		l := firstPos[s]
		if l != -2 {
			res = max(res, i-l)
		} else {
			firstPos[s] = i
		}
	}
	return
}
